parameters.jsCode:
const user = $('Loop Over Items').item.json;
const allTrainings = $input.all().map(i => i.json);

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const weekTrainings = allTrainings.filter(t => t.date && new Date(t.date) >= weekAgo);

const totalKm = weekTrainings.reduce((sum, t) => sum + (Number(t.distance) || 0), 0) / 1000;
const sessionCount = weekTrainings.length;

const zoneDagilimi = {};
for (const t of weekTrainings) {
  const z = t.effect || 'bilinmiyor';
  zoneDagilimi[z] = (zoneDagilimi[z] || 0) + 1;
}

return [{ json: {
  chat_id: user.chat_id,
  user_name: user.user,
  goal: user.goal,
  notion_link: user.link,
  toplam_km: Math.round(totalKm * 10) / 10,
  antrenman_sayisi: sessionCount,
  zone_dagilimi: zoneDagilimi,
  antrenmanlar: weekTrainings.map(t => ({
    tarih: t.date,
    tur: t.training,
    mesafe_km: Math.round((Number(t.distance) || 0) / 1000 * 10) / 10,
    zone: t.effect
  }))
} }];

