const activityDate = new Date($('Strava Trigger').item.json.object_data.start_date);
const planStart = new Date($('Get row(s) in sheet1').item.json.plan_start_date);

const actUTC = Date.UTC(activityDate.getUTCFullYear(), activityDate.getUTCMonth(), activityDate.getUTCDate());
const planUTC = Date.UTC(planStart.getUTCFullYear(), planStart.getUTCMonth(), planStart.getUTCDate());

const gunFarki = Math.floor((actUTC - planUTC) / 86400000);
const haftaNo = Math.floor(gunFarki / 7) + 1;
const gunAdlari = ['Pazar','Pazartesi','Sali','Carsamba','Persembe','Cuma','Cumartesi'];
const gunAdi = gunAdlari[activityDate.getUTCDay()];

return [{ json: { ...$json, plan_hafta_no: haftaNo, plan_gun_adi: gunAdi } }];

